def reset_index(
    self: T_Dataset,
    dims_or_levels: Hashable | Sequence[Hashable],
    drop: bool = False,
) -> T_Dataset:
    """Reset the specified index(es) or multi-index level(s).

    Parameters
    ----------
    dims_or_levels : Hashable or Sequence of Hashable
        Name(s) of the dimension(s) and/or multi-index level(s) that will
        be reset.
    drop : bool, default: False
        If True, remove the specified indexes and/or multi-index levels
        instead of extracting them as new coordinates (default: False).

    Returns
    -------
    obj : Dataset
        Another dataset, with this dataset's data but replaced coordinates.

    See Also
    --------
    Dataset.set_index
    """
    if isinstance(dims_or_levels, str) or not isinstance(dims_or_levels, Sequence):
        dims_or_levels = [dims_or_levels]

    invalid_coords = set(dims_or_levels) - set(self._indexes)
    if invalid_coords:
        raise ValueError(
            f"{tuple(invalid_coords)} are not coordinates with an index"
        )

    drop_indexes: list[Hashable] = []
    drop_variables: list[Hashable] = []
    seen_indexes: list[Index] = []
    new_indexes: dict[Hashable, Index] = {}
    new_variables: dict[Hashable, Variable] = {}

    for name in dims_or_levels:
        index = self._indexes[name]
        if index in seen_indexes:
            continue
        seen_indexes.append(index)

        idx_coord_names = set(self.xindexes.get_all_coords(name))
        drop_indexes.extend(idx_coord_names)

        if isinstance(index, PandasMultiIndex):
            level_names = index.index.names
            keep_level_vars = {
                k: self._variables[k]
                for k in level_names
                if k not in dims_or_levels
            }

            if index.dim not in dims_or_levels and keep_level_vars:
                # do not drop or convert the multi-index if there remains
                # at least one level and the dimension itself is not reset
                idx = index.keep_levels(keep_level_vars)
                idx_vars = idx.create_variables(keep_level_vars)
                new_indexes.update({k: idx for k in idx_vars})
                new_variables.update(idx_vars)
                if not isinstance(idx, PandasMultiIndex):
                    # multi-index reduced to single index: level coordinate
                    # is renamed to the dimension coordinate
                    drop_variables.extend(keep_level_vars)
                drop_or_convert_names = [
                    k for k in level_names if k in dims_or_levels
                ]
            else:
                # always drop the multi-index dimension variable
                drop_variables.append(index.dim)
                drop_or_convert_names = list(level_names)

            if drop:
                drop_variables.extend(drop_or_convert_names)
            else:
                new_variables.update(
                    {
                        k: self._variables[k].to_base_variable()
                        for k in drop_or_convert_names
                    }
                )
        else:
            if drop:
                drop_variables.extend(idx_coord_names)
            else:
                new_variables.update(
                    {
                        k: self._variables[k].to_base_variable()
                        for k in idx_coord_names
                    }
                )

    indexes = {k: v for k, v in self._indexes.items() if k not in drop_indexes}
    indexes.update(new_indexes)

    variables = {
        k: v for k, v in self._variables.items() if k not in drop_variables
    }
    variables.update(new_variables)

    coord_names = (set(new_variables) | self._coord_names) & set(variables)

    return self._replace_with_new_dims(
        variables, coord_names=coord_names, indexes=indexes
    )

